                if s == '.':
                    continue
                m |= 1 if s == color else 2
            if m == 1:
                own += 1
            elif m == 2:
                foe += 1
    return own - foe >= 2

MOTIF_NAME = 'tiger mouth shape advantage'
MOTIF_DESCRIPTION = 'An empty interior point with exactly three orthogonal neighbors of one color and the fourth orthogonal neighbor empty is a tiger mouth, a strong flexible shape for both attack and defense, and the evaluated side forms clearly more tiger mouths than the opponent.'

def motif(board_rows: list[str], color: str) -> bool:
    br = board_rows
    opp = 'W' if color == 'B' else 'B'
    own = 0
    foe = 0
    for r in range(1, 18):
        up = br[r - 1]
        mid = br[r]
        dn = br[r + 1]
        for c in range(1, 18):
            if mid[c] != '.':
                continue
            oc = 0
            xc = 0
            em = 0
            for s in (up[c], dn[c], mid[c - 1], mid[c + 1]):
                if s == color:
                    oc += 1
                elif s == opp:
                    xc += 1
                elif s == '.':
                    em += 1
            if em == 1:
                if oc == 3:
                    own += 1
                elif xc == 3:
                    foe += 1
    return own - foe >= 3
